using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    private static Task<AuthorizationOutcome> Authorize(HttpPaymentGateway gateway) =>
        gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Authorize(Gateway());

        var received = Assert.Single(provider.Requests);
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.ContentType);
        using var json = JsonDocument.Parse(received.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(Gateway()));
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(Gateway()));
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"a1","status":"approved","score":0.3}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(Gateway()));
    }

    [Fact]
    public async Task A_payment_required_refusal_is_a_decline_not_an_error()
    {
        provider.Respond(402, """{"error":"insufficient_funds"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(Gateway()));
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"status":"pending_review"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(Gateway()));
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        provider.Respond(200, """{"decision":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(Gateway()));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_decisions(int status)
    {
        provider.Respond(status, """{"status":"approved"}""");

        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(Gateway()));
    }

    [Fact]
    public async Task An_answer_that_is_not_json_surfaces_as_an_error()
    {
        provider.Respond(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize(Gateway()));
    }

    public void Dispose() => provider.Dispose();

    private sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);

    // A real HTTP server on a loopback port, standing in for the provider.
    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<ReceivedRequest> requests = [];
        private int status = 200;
        private string body = "";

        public FakeProvider()
        {
            // Retry on port collisions since the port is picked by probing.
            for (var attempt = 0; ; attempt++)
            {
                var port = Random.Shared.Next(20000, 60000);
                try
                {
                    listener.Prefixes.Add($"http://127.0.0.1:{port}/");
                    listener.Start();
                    BaseAddress = new Uri($"http://127.0.0.1:{port}");
                    break;
                }
                catch (HttpListenerException) when (attempt < 10)
                {
                    listener.Prefixes.Clear();
                }
            }
            _ = Task.Run(Serve);
        }

        public Uri BaseAddress { get; private set; } = null!;

        public IReadOnlyList<ReceivedRequest> Requests { get { lock (requests) return [.. requests]; } }

        public void Respond(int statusCode, string responseBody) => (status, body) = (statusCode, responseBody);

        private async Task Serve()
        {
            while (listener.IsListening)
            {
                try
                {
                    var context = await listener.GetContextAsync();
                    using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                    var received = new ReceivedRequest(
                        context.Request.HttpMethod,
                        context.Request.Url!.AbsolutePath,
                        context.Request.ContentType,
                        await reader.ReadToEndAsync());
                    lock (requests) requests.Add(received);

                    var bytes = Encoding.UTF8.GetBytes(body);
                    context.Response.StatusCode = status;
                    context.Response.ContentType = "application/json";
                    await context.Response.OutputStream.WriteAsync(bytes);
                    context.Response.Close();
                }
                catch (Exception) when (!listener.IsListening) { }
            }
        }

        public void Dispose() => listener.Close();
    }
}
